import"./chunk-2NFLSA4Y.js";var i={collisions:{theory:{concept:"A collision is a short interaction of bodies during which their velocities change sharply. [[If external forces are negligible, the total momentum of the colliding bodies stays the same.]] In an inelastic collision part of the kinetic energy turns into deformation, heat or sound \u2014 it is not destroyed; in a perfectly inelastic collision the bodies stick together and move on with a common velocity."},section:{momentum:{title:"Momentum is conserved",text:"Momentum is mass times velocity and has a direction. Add the signed momentum of both bodies before and after the collision: the totals are equal. A body moving left has negative velocity in this model."},elastic:{title:"Perfectly elastic collision",text:"[[At e = 1, both total momentum and total kinetic energy are conserved.]] For equal masses, if the second body starts at rest, the first stops and the second leaves with its speed."},inelastic:{title:"Completely inelastic collision",text:"At e = 0, the bodies leave with the same velocity and remain in contact. [[Momentum is still conserved, but kinetic energy falls.]] The missing kinetic energy becomes internal energy such as heat and deformation."},coefficient:{title:"Between the two extremes",text:"The restitution coefficient e compares the speed at which the bodies separate with the speed at which they approach. Values between 0 and 1 model partly inelastic collisions. The energy loss rises as e decreases for fixed masses and initial velocities."},walls:{title:"Collisions in a closed room",text:"The walls are fixed and perfectly elastic in this model, so a body reverses its velocity at a wall. After bouncing, it can collide with the other body again. The wall exerts an external impulse on the two-body system: their combined momentum can change, while momentum of bodies plus walls is conserved. If e = 0, the bodies stay joined and bounce together."},try:{title:"Try it",text:"Run once with e = 1, then reset and run with e = 0 without changing either mass or starting speed. Compare the momentum, kinetic energy and two final velocities. Next, change one mass."}},formula:{momentum:"Total momentum before and after impact",energy:"Kinetic energy of one body",restitution:"Separation speed divided by approach speed"},variable:{mass:"Masses of bodies 1 and 2",initialVelocity:"Velocities before impact",finalVelocity:"Velocities after impact",restitution:"Coefficient of restitution"},assumption:{isolated:"Without walls, the bodies move along one line without external forces or friction, so their total momentum is conserved.",instant:"Impact is instantaneous; the model does not simulate how long deformation lasts or where the lost kinetic energy goes in detail.",drawing:"Body diameters and the track are illustrative. Body size does not change with mass; only the labeled mass affects the calculation.",walls:"When the room is closed, fixed walls reflect bodies perfectly elastically. Wall impacts can change the momentum of the two bodies together. At e = 0 the bodies remain joined and reflect as one pair."},param:{closedSpace:"Closed room with walls",restitution:"Restitution coefficient",mass1:"Mass of body 1",mass2:"Mass of body 2",initialVelocity1:"Initial velocity of body 1",initialVelocity2:"Initial velocity of body 2",timeStep:"Simulation timestep"},hint:{closedSpace:"Turn on fixed walls to see repeated collisions. Wall bounces are perfectly elastic.",restitution:"1 = perfectly elastic; 0 = completely inelastic. Values between them lose part of the kinetic energy.",velocity:"Right is positive and left is negative."},preset:{elastic:"Elastic (e = 1)",inelastic:"Completely inelastic (e = 0)"},measure:{velocity1:"Velocity of body 1",velocity2:"Velocity of body 2",momentum:"Momentum of both bodies",kineticEnergy:"Total kinetic energy",energyLoss:"Kinetic energy converted",initialMomentum:"Initial momentum",initialEnergy:"Initial kinetic energy",bodyCollisions:"Body collisions",wallReflections:"Wall reflections",wallImpulse:"Impulse from walls"},visual:{vectors:"Velocity arrows"},view:{before:"Before impact",bodyImpact:"Body collision",wallImpact:"Wall bounce",room:"Closed room",wall:"Wall",after:"After impact",scale:"Illustrative body sizes"},graph:{momentum:"Momentum before and after",energy:"Kinetic energy before and after"},challenge:{elastic:{title:"Energy stays kinetic",description:"Run a perfectly elastic collision and keep kinetic energy.",hint:"Choose e = 1 and run until the objects collide."},stick:{title:"Move together",description:"Make both objects leave with the same velocity.",hint:"Choose e = 0 and run the collision."},loss:{title:"Convert five joules",description:"Convert at least 5 J of kinetic energy during impact.",hint:"Use a low restitution and make the bodies approach quickly."},return:{title:"Meet again",description:"In the closed room, make the bodies collide twice and bounce from a wall.",hint:"Turn on the closed room and run the simulation."}}}},o={sim:i};export{o as default,i as sim};
